using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 defaults to UTF-8 entry names (sets the EFS flag).
        // Legacy Java consumer expects Shift-JIS, so specify the encoding explicitly.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("shift_jis");

        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create);
        archive.CreateEntry("レポート/月次.csv", shiftJis);  // Japanese path
        archive.CreateEntry("données/résumé.txt", shiftJis); // French accented
    }
}

